const raw = $input.first().json;
const body = (raw && typeof raw.body === 'object' && raw.body !== null) ? raw.body : raw;
const event = String(body.event || '');
const channels = body.channelsConfig || {};
const b64 = obj => Buffer.from(JSON.stringify(obj), 'utf8').toString('base64');

// 1. Checagem de Auto-Mod + Comando !custom + Sticky Message
if (event === 'discord.mod_check') {
  const guildId = String(body.guildId || '');
  const channelId = String(body.channelId || '');
  const messageId = String(body.messageId || '');
  const content = String(body.content || '');
  const commandName = body.commandName ? String(body.commandName).toLowerCase() : null;
  const author = body.author || {};
  const isMod = Boolean(author.isMod);

  let violationReason = null;
  if (!isMod) {
    if (/(discord\.gg\/|discord\.com\/invite\/)/i.test(content)) {
      violationReason = 'Link de convite do Discord não autorizado (Auto-Mod)';
    } else if (/@(everyone|here)/i.test(content)) {
      violationReason = 'Menção em massa não autorizada (Auto-Mod)';
    } else if (/(free\s+nitro|steam\s+gift|airdrop\s+crypto)/i.test(content)) {
      violationReason = 'Padrão suspeito de spam/golpe (Auto-Mod)';
    }
  }

  const payload = {
    guildId,
    channelId,
    userId: String(author.id || ''),
    commandName,
    violationReason
  };

  const sql = `
    WITH p AS (SELECT convert_from(decode($1, 'base64'), 'UTF8')::jsonb AS j),
    ins_log AS (
      INSERT INTO discord_mod_logs (guild_id, user_id, moderator_id, action, reason)
      SELECT p.j->>'guildId', p.j->>'userId', 'usami-automod', 'delete_message', p.j->>'violationReason'
      FROM p
      WHERE COALESCE(p.j->>'violationReason', '') <> ''
      RETURNING id
    ),
    cmd AS (
      SELECT command_name, response_text
      FROM discord_custom_commands
      WHERE guild_id = (SELECT p.j->>'guildId' FROM p)
        AND command_name = (SELECT p.j->>'commandName' FROM p)
      LIMIT 1
    ),
    sticky AS (
      SELECT channel_id, content, last_message_id
      FROM discord_sticky_messages
      WHERE channel_id = (SELECT p.j->>'channelId' FROM p)
      LIMIT 1
    )
    SELECT jsonb_build_object(
      'action', 'mod_check',
      'loggedId', (SELECT id FROM ins_log LIMIT 1),
      'customCmd', (SELECT row_to_json(cmd) FROM cmd LIMIT 1),
      'sticky', (SELECT row_to_json(sticky) FROM sticky LIMIT 1)
    ) AS result;
  `;

  return [{ json: { mode: 'mod_check', event, body, channels, violationReason, sql, payloadB64: b64(payload) } }];
}

// 2. Reaction Roles
if (event === 'discord.reaction_add' || event === 'discord.reaction_remove') {
  const payload = {
    messageId: String(body.messageId || ''),
    emoji: String(body.emoji || '')
  };
  const sql = `
    WITH p AS (SELECT convert_from(decode($1, 'base64'), 'UTF8')::jsonb AS j),
    rr AS (
      SELECT role_id, guild_id
      FROM discord_reaction_roles
      WHERE message_id = (SELECT p.j->>'messageId' FROM p)
        AND emoji = (SELECT p.j->>'emoji' FROM p)
      LIMIT 1
    )
    SELECT jsonb_build_object(
      'action', 'reaction_role',
      'role', (SELECT row_to_json(rr) FROM rr LIMIT 1)
    ) AS result;
  `;
  return [{ json: { mode: 'reaction', event, body, channels, sql, payloadB64: b64(payload) } }];
}

// 3. Slash Commands de Moderacao & Estrutura
if (event === 'discord.slash_command') {
  const cmd = String(body.commandName || '');
  const opts = body.options || {};
  const user = body.user || {};
  const guildId = String(body.guildId || '');
  const channelId = String(body.channelId || '');
  const userId = String(user.id || '');
  const username = String(user.globalName || user.username || 'usuário');

  if (cmd === 'cmd') {
    const acao = String(opts.acao || 'listar');
    const nome = String(opts.nome || '').trim().replace(/^!/, '').toLowerCase().slice(0, 50);
    const resposta = String(opts.resposta || '').trim().slice(0, 1500);
    const payload = { acao, guildId, nome, resposta, userId };
    let sql = '';
    if (acao === 'criar') {
      sql = `
        WITH p AS (SELECT convert_from(decode($1, 'base64'), 'UTF8')::jsonb AS j),
        up AS (
          INSERT INTO discord_custom_commands (guild_id, command_name, response_text, created_by)
          SELECT p.j->>'guildId', p.j->>'nome', p.j->>'resposta', p.j->>'userId' FROM p
          WHERE COALESCE(p.j->>'nome', '') <> '' AND COALESCE(p.j->>'resposta', '') <> ''
          ON CONFLICT (guild_id, command_name) DO UPDATE SET response_text = EXCLUDED.response_text
          RETURNING command_name
        )
        SELECT jsonb_build_object('action', 'cmd_criar', 'saved', (SELECT command_name FROM up LIMIT 1)) AS result;
      `;
    } else if (acao === 'remover') {
      sql = `
        WITH p AS (SELECT convert_from(decode($1, 'base64'), 'UTF8')::jsonb AS j),
        del AS (
          DELETE FROM discord_custom_commands
          WHERE guild_id = (SELECT p.j->>'guildId' FROM p) AND command_name = (SELECT p.j->>'nome' FROM p)
          RETURNING command_name
        )
        SELECT jsonb_build_object('action', 'cmd_remover', 'deleted', (SELECT command_name FROM del LIMIT 1)) AS result;
      `;
    } else {
      sql = `
        WITH p AS (SELECT convert_from(decode($1, 'base64'), 'UTF8')::jsonb AS j),
        rows AS (
          SELECT command_name, LEFT(response_text, 60) AS preview
          FROM discord_custom_commands
          WHERE guild_id = (SELECT p.j->>'guildId' FROM p)
          ORDER BY command_name LIMIT 25
        )
        SELECT jsonb_build_object('action', 'cmd_listar', 'list', COALESCE((SELECT jsonb_agg(row_to_json(rows)) FROM rows), '[]'::jsonb)) AS result;
      `;
    }
    return [{ json: { mode: 'slash', commandName: cmd, body, channels, sql, payloadB64: b64(payload) } }];
  }

  if (cmd === 'sticky') {
    const acao = String(opts.acao || 'definir');
    const texto = String(opts.texto || '').trim().slice(0, 1500);
    const payload = { acao, guildId, channelId, texto };
    const sql = acao === 'remover'
      ? `
        WITH p AS (SELECT convert_from(decode($1, 'base64'), 'UTF8')::jsonb AS j),
        del AS (DELETE FROM discord_sticky_messages WHERE channel_id = (SELECT p.j->>'channelId' FROM p) RETURNING last_message_id)
        SELECT jsonb_build_object('action', 'sticky_remover', 'deleted', (SELECT row_to_json(del) FROM del LIMIT 1)) AS result;
      `
      : `
        WITH p AS (SELECT convert_from(decode($1, 'base64'), 'UTF8')::jsonb AS j),
        up AS (
          INSERT INTO discord_sticky_messages (channel_id, guild_id, content, updated_at)
          SELECT p.j->>'channelId', p.j->>'guildId', p.j->>'texto', NOW() FROM p
          WHERE COALESCE(p.j->>'texto', '') <> ''
          ON CONFLICT (channel_id) DO UPDATE SET content = EXCLUDED.content, updated_at = NOW()
          RETURNING channel_id, content, last_message_id
        )
        SELECT jsonb_build_object('action', 'sticky_definir', 'sticky', (SELECT row_to_json(up) FROM up LIMIT 1)) AS result;
      `;
    return [{ json: { mode: 'slash', commandName: cmd, body, channels, sql, payloadB64: b64(payload) } }];
  }

  if (cmd === 'reactionrole') {
    const messageId = String(opts.message_id || '').trim();
    const emoji = String(opts.emoji || '').trim();
    const roleId = String(opts.role || '').trim();
    const payload = { guildId, channelId, messageId, emoji, roleId };
    const sql = `
      WITH p AS (SELECT convert_from(decode($1, 'base64'), 'UTF8')::jsonb AS j),
      up AS (
        INSERT INTO discord_reaction_roles (guild_id, channel_id, message_id, emoji, role_id)
        SELECT p.j->>'guildId', p.j->>'channelId', p.j->>'messageId', p.j->>'emoji', p.j->>'roleId' FROM p
        ON CONFLICT (message_id, emoji) DO UPDATE SET role_id = EXCLUDED.role_id
        RETURNING id, message_id, emoji, role_id
      )
      SELECT jsonb_build_object('action', 'reactionrole', 'saved', (SELECT row_to_json(up) FROM up LIMIT 1)) AS result;
    `;
    return [{ json: { mode: 'slash', commandName: cmd, body, channels, sql, payloadB64: b64(payload) } }];
  }

  if (cmd === 'ticket') {
    const acao = String(opts.acao || 'abrir');
    const assunto = String(opts.assunto || 'Suporte Geral').trim().slice(0, 120);
    const payload = { acao, guildId, channelId, userId, username, assunto };
    const sql = acao === 'fechar'
      ? `
        WITH p AS (SELECT convert_from(decode($1, 'base64'), 'UTF8')::jsonb AS j),
        cl AS (
          UPDATE discord_tickets SET status = 'closed', closed_at = NOW()
          WHERE channel_id = (SELECT p.j->>'channelId' FROM p) AND status = 'open'
          RETURNING id, channel_id, topic
        )
        SELECT jsonb_build_object('action', 'ticket_fechar', 'closed', (SELECT row_to_json(cl) FROM cl LIMIT 1)) AS result;
      `
      : `
        WITH p AS (SELECT convert_from(decode($1, 'base64'), 'UTF8')::jsonb AS j)
        SELECT jsonb_build_object(
          'action', 'ticket_abrir',
          'openCount', (SELECT COUNT(*) FROM discord_tickets WHERE guild_id = (SELECT p.j->>'guildId' FROM p) AND user_id = (SELECT p.j->>'userId' FROM p) AND status = 'open')
        ) AS result;
      `;
    return [{ json: { mode: 'slash', commandName: cmd, body, channels, sql, payloadB64: b64(payload) } }];
  }
}

throw new Error(`Evento de moderação não reconhecido: ${event}`);

const ctx = $('Avaliar Moderacao e Estrutura').item.json;
const res = ($input.first().json && $input.first().json.result) || {};
const body = ctx.body || {};
const channels = ctx.channels || {};
const calls = [];

const addCall = (method, url, payload = null, meta = {}) => {
  calls.push({
    json: {
      method,
      url,
      hasBody: payload !== null,
      bodyJson: payload !== null ? JSON.stringify(payload) : '',
      meta
    }
  });
};

if (ctx.mode === 'mod_check') {
  if (ctx.violationReason) {
    addCall('DELETE', `https://discord.com/api/v10/channels/${body.channelId}/messages/${body.messageId}`);
    addCall('POST', `https://discord.com/api/v10/channels/${body.channelId}/messages`, {
      content: `⚠️ <@${body.author.id}>, sua mensagem foi removida: **${ctx.violationReason}**.`
    });
    if (channels.modLogChannelId) {
      addCall('POST', `https://discord.com/api/v10/channels/${channels.modLogChannelId}/messages`, {
        embeds: [{
          title: '🛡️ Ação de Auto-Moderação',
          color: 15548997,
          fields: [
            { name: 'Usuário', value: `<@${body.author.id}> (${body.author.username})`, inline: true },
            { name: 'Canal', value: `<#${body.channelId}>`, inline: true },
            { name: 'Motivo', value: ctx.violationReason, inline: false }
          ],
          timestamp: new Date().toISOString()
        }]
      });
    }
    return calls;
  }

  if (res.customCmd && res.customCmd.response_text) {
    addCall('POST', `https://discord.com/api/v10/channels/${body.channelId}/messages`, {
      content: res.customCmd.response_text
    });
  }

  if (res.sticky && res.sticky.content) {
    if (res.sticky.last_message_id) {
      addCall('DELETE', `https://discord.com/api/v10/channels/${body.channelId}/messages/${res.sticky.last_message_id}`);
    }
    addCall('POST', `https://discord.com/api/v10/channels/${body.channelId}/messages`, {
      embeds: [{
        title: '📌 Mensagem Fixada',
        description: res.sticky.content,
        color: 16754377
      }]
    }, { updateStickyChannelId: body.channelId });
  }
}

if (ctx.mode === 'reaction') {
  const role = res.role;
  if (role && role.role_id) {
    const method = ctx.event === 'discord.reaction_add' ? 'PUT' : 'DELETE';
    addCall(method, `https://discord.com/api/v10/guilds/${body.guildId}/members/${body.userId}/roles/${role.role_id}`);
  }
}

if (ctx.mode === 'slash') {
  const cmd = ctx.commandName;
  const patchUrl = body.webhookPatchUrl;
  if (cmd === 'cmd') {
    if (res.action === 'cmd_criar') {
      addCall('PATCH', patchUrl, {
        content: res.saved ? `✅ Comando customizado \`!${res.saved}\` salvo!` : 'Informe `nome` e `resposta` para criar o comando.'
      });
    } else if (res.action === 'cmd_remover') {
      addCall('PATCH', patchUrl, {
        content: res.deleted ? `🗑️ Comando \`!${res.deleted}\` removido.` : 'Comando não encontrado.'
      });
    } else {
      const list = Array.isArray(res.list) ? res.list : [];
      const desc = list.length
        ? list.map(c => `• \`!${c.command_name}\` — ${c.preview}`).join('\n')
        : 'Nenhum comando customizado configurado ainda.';
      addCall('PATCH', patchUrl, { embeds: [{ title: '⚡ Comandos Customizados', description: desc, color: 16735870 }] });
    }
  } else if (cmd === 'sticky') {
    if (res.action === 'sticky_remover') {
      if (res.deleted?.last_message_id) {
        addCall('DELETE', `https://discord.com/api/v10/channels/${body.channelId}/messages/${res.deleted.last_message_id}`);
      }
      addCall('PATCH', patchUrl, { content: '📌 Sticky message removida deste canal.' });
    } else if (res.sticky) {
      if (res.sticky.last_message_id) {
        addCall('DELETE', `https://discord.com/api/v10/channels/${body.channelId}/messages/${res.sticky.last_message_id}`);
      }
      addCall('PATCH', patchUrl, { content: '📌 Sticky message ativada neste canal!' });
      addCall('POST', `https://discord.com/api/v10/channels/${body.channelId}/messages`, {
        embeds: [{ title: '📌 Mensagem Fixada', description: res.sticky.content, color: 16754377 }]
      }, { updateStickyChannelId: body.channelId });
    } else {
      addCall('PATCH', patchUrl, { content: 'Informe o `texto` da sticky message.' });
    }
  } else if (cmd === 'reactionrole') {
    const s = res.saved || {};
    addCall('PATCH', patchUrl, {
      content: `🎭 Reaction Role configurado: reagir com ${s.emoji} na mensagem \`${s.message_id}\` atribui <@&${s.role_id}>.`
    });
    if (s.message_id && s.emoji) {
      addCall('PUT', `https://discord.com/api/v10/channels/${body.channelId}/messages/${s.message_id}/reactions/${encodeURIComponent(s.emoji)}/@me`);
    }
  } else if (cmd === 'ticket') {
    if (res.action === 'ticket_fechar') {
      if (res.closed) {
        addCall('PATCH', patchUrl, { content: `🔒 Ticket **#${res.closed.id}** encerrado. Este canal será removido em instantes.` });
        addCall('DELETE', `https://discord.com/api/v10/channels/${body.channelId}`);
      } else {
        addCall('PATCH', patchUrl, { content: 'Este canal não é um ticket aberto.' });
      }
    } else {
      if (Number(res.openCount || 0) >= 3) {
        addCall('PATCH', patchUrl, { content: 'Você já possui 3 tickets abertos. Feche um antes de abrir outro.' });
      } else {
        const topic = String(body.options?.assunto || 'Suporte Geral').slice(0, 120);
        const safeUser = String(body.user?.username || 'membro').toLowerCase().replace(/[^a-z0-9-]/g, '').slice(0, 18) || 'membro';
        const channelPayload = {
          name: `ticket-${safeUser}`,
          type: 0,
          topic: `Ticket de ${body.user?.username || 'membro'} | ${topic}`,
          permission_overwrites: [
            { id: body.guildId, type: 0, deny: '1024' },
            { id: body.user?.id, type: 1, allow: '68608' }
          ]
        };
        if (channels.ticketCategoryId) channelPayload.parent_id = channels.ticketCategoryId;
        addCall('POST', `https://discord.com/api/v10/guilds/${body.guildId}/channels`, channelPayload, {
          createdTicket: true,
          guildId: body.guildId,
          userId: body.user?.id,
          username: body.user?.globalName || body.user?.username || 'membro',
          topic,
          patchUrl
        });
      }
    }
  }
}

return calls;

const responses = $input.all();
const allCalls = $('Montar Acoes Moderacao').all().filter(c => c.json.hasBody);
const out = [];

for (let i = 0; i < responses.length; i++) {
  const res = responses[i].json || {};
  const meta = (allCalls[i] && allCalls[i].json && allCalls[i].json.meta) || {};
  if (meta.updateStickyChannelId && res.id) {
    const p = { channelId: meta.updateStickyChannelId, messageId: String(res.id) };
    out.push({
      json: {
        sql: `WITH p AS (SELECT convert_from(decode($1, 'base64'), 'UTF8')::jsonb AS j) UPDATE discord_sticky_messages SET last_message_id = p.j->>'messageId', updated_at = NOW() FROM p WHERE channel_id = p.j->>'channelId';`,
        payloadB64: Buffer.from(JSON.stringify(p), 'utf8').toString('base64'),
        discordFollowups: []
      }
    });
  }
  if (meta.createdTicket && res.id) {
    const p = {
      guildId: meta.guildId,
      channelId: String(res.id),
      userId: meta.userId,
      username: meta.username,
      topic: meta.topic
    };
    out.push({
      json: {
        sql: `WITH p AS (SELECT convert_from(decode($1, 'base64'), 'UTF8')::jsonb AS j) INSERT INTO discord_tickets (guild_id, channel_id, user_id, username, topic) SELECT p.j->>'guildId', p.j->>'channelId', p.j->>'userId', p.j->>'username', p.j->>'topic' FROM p;`,
        payloadB64: Buffer.from(JSON.stringify(p), 'utf8').toString('base64'),
        patchUrl: meta.patchUrl,
        patchBody: JSON.stringify({ content: `🎫 Ticket criado com sucesso em <#${res.id}>!` }),
        ticketChannelUrl: `https://discord.com/api/v10/channels/${res.id}/messages`,
        ticketWelcomeBody: JSON.stringify({
          content: `<@${meta.userId}>`,
          embeds: [{
            title: '🎫 Ticket de Suporte',
            description: `Assunto: **${meta.topic}**\nDescreva como podemos ajudar. Quando terminar, use \`/ticket fechar\`.`,
            color: 16735870
          }]
        })
      }
    });
  }
}
return out;
